import argparse, hashlib, json
from pathlib import Path
import numpy as np
import pyarrow as pa
import pyarrow.compute as pc
import pyarrow.parquet as pq
p=argparse.ArgumentParser(); p.add_argument('--phase',required=True); a=p.parse_args()
root=Path('/workspace/s2r/outputs/v3-sim-checks')
result={'phase':a.phase,'method':'Per episode, row order by frame_index; contiguous raw primitive column values in their stored dtype; SHA-256 over C-order bytes. Videos excluded.','recipes':{}}
for name in ('scripted','stack_two_cubes','stack_bowls'):
    report=root/a.phase/(name+'-report.json')
    item={'report_exists':report.exists(),'episodes':[]}
    if report.exists():
        data=json.loads(report.read_text()); item['report']=data
    files=sorted((root/a.phase/'datasets'/name/'data').rglob('*.parquet'))
    item['parquet_files']=[str(f) for f in files]
    if files:
        table=pa.concat_tables([pq.ParquetFile(f).read(columns=['episode_index','frame_index','action','observation.state']) for f in files])
        for eid in sorted(set(table['episode_index'].to_pylist())):
            episode=table.filter(pc.equal(table['episode_index'],eid)); episode=episode.take(pc.sort_indices(episode,sort_keys=[('frame_index','ascending')]))
            entry={'episode_index':eid,'frames':episode.num_rows,'columns':{}}
            for col in ('action','observation.state'):
                column=episode[col].combine_chunks()
                if column.null_count: raise ValueError('Null recorded array')
                values=column.flatten().to_numpy(zero_copy_only=False)
                array=np.ascontiguousarray(values.reshape(episode.num_rows,-1))
                entry['columns'][col]={'sha256':hashlib.sha256(array.tobytes(order='C')).hexdigest(),'dtype':str(array.dtype),'shape':list(array.shape)}
                out=root/a.phase/'arrays'/name; out.mkdir(parents=True,exist_ok=True); np.save(out/(str(eid)+'-'+col+'.npy'),array)
            item['episodes'].append(entry)
    result['recipes'][name]=item
(root/a.phase/'array_hashes.json').write_text(json.dumps(result,indent=2)+'\n'); print(json.dumps({name:{'accepted_episodes':len(d['episodes']),'hashes':d['episodes']} for name,d in result['recipes'].items()},indent=2))

